fn same(aaa: []const u8, bbb: []const u8) bool { return std.mem.eql(u8, aaa, bbb); }
pub fn lab(conf: cfgz.Conf, key: []const u8) []const []const u8 { if (conf.labl_over.map.get(key)) |ovr| return ovr; if (same(key, "post_open")) return conf.labl_post_open; if (same(key, "post_boxz")) return conf.labl_post_boxz; if (same(key, "post_subm")) return conf.labl_post_subm; if (same(key, "comm_boxz")) return conf.labl_comm_boxz; if (same(key, "repl_btnz")) return conf.labl_repl_btnz; if (same(key, "dmsg_boxz")) return conf.labl_dmsg_boxz; if (same(key, "mark_titl")) return conf.labl_mark_titl; if (same(key, "mark_pric")) return conf.labl_mark_pric; if (same(key, "mark_desc")) return conf.labl_mark_desc; if (same(key, "mark_subm")) return conf.labl_mark_subm; if (same(key, "mark_done")) return conf.labl_mark_done; if (same(key, "mark_renw")) return conf.labl_mark_renw; if (same(key, "mark_sold")) return conf.labl_mark_sold; if (same(key, "grou_join")) return conf.labl_grou_join; if (same(key, "frie_addz")) return conf.labl_frie_addz; for (PACK) |ent| { if (same(ent.key, key)) return ent.labs; } return &.{}; }
pub fn known(key: []const u8) bool { const dflt: cfgz.Conf = .{}; return lab(dflt, key).len > 0; }
